核心 Java 实现代码
基于 Spring Boot + Spring Data Redis 标准技术栈，全链路贴合大厂生产规范。
Lua 脚本预加载配置
技术亮点：提前编译脚本 + evalsha 调用，避免每次请求传输完整脚本，减少网络 IO 与 Redis 重复编译开销，性能比直接 eval 提升 30% 以上
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.io.ClassPathResource;
import org.springframework.data.redis.core.script.DefaultRedisScript;

@Configuration
public class RedisLuaConfig {

    @Bean
    public DefaultRedisScript<Long> balanceDeductScript() {
        DefaultRedisScript<Long> script = new DefaultRedisScript<>();
        // 脚本存放路径：resources/lua/balance_deduct.lua
        script.setScriptLocation(new ClassPathResource("lua/balance_deduct.lua"));
        script.setResultType(Long.class);
        return script;
    }
}

核心记账服务实现
技术亮点：全程无任何业务锁 / 分布式锁，原子性由 Lua 脚本兜底；统一返回码枚举，全链路语义清晰；金额以分为单位规避浮点精度问题；内置幂等兼容重试场景
import lombok.RequiredArgsConstructor;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.data.redis.core.script.DefaultRedisScript;
import org.springframework.stereotype.Service;
import java.util.Arrays;

@Service
@RequiredArgsConstructor
public class AccountBalanceService {

    private final StringRedisTemplate stringRedisTemplate;
    private final DefaultRedisScript<Long> balanceDeductScript;

    // 余额key前缀
    private static final String BALANCE_KEY_PREFIX = "account:balance:";
    // 幂等key前缀
    private static final String IDEMPOTENT_KEY_PREFIX = "account:deduct:idempotent:";
    // 幂等key过期时间：24小时
    private static final long IDEMPOTENT_EXPIRE_SEC = 86400L;

    /**
     * 余额扣减核心方法
     * @param accountId 账户ID
     * @param deductAmount 扣减金额（单位：分，规避浮点精度问题）
     * @param requestNo 业务唯一流水号（幂等校验用）
     * @return 扣减结果枚举
     */
    public DeductResultEnum deduct(Long accountId, Long deductAmount, String requestNo) {
        // 组装Redis Key
        String balanceKey = BALANCE_KEY_PREFIX + accountId;
        String idempotentKey = IDEMPOTENT_KEY_PREFIX + requestNo;

        // 执行Lua脚本：所有逻辑原子串行执行，无并发竞态
        Long result = stringRedisTemplate.execute(
                balanceDeductScript,
                Arrays.asList(balanceKey, idempotentKey),
                String.valueOf(deductAmount),
                String.valueOf(IDEMPOTENT_EXPIRE_SEC)
        );

        // 按约定返回码映射业务结果
        return switch (result.intValue()) {
            case 0 -> DeductResultEnum.SUCCESS;
            case 1 -> DeductResultEnum.REPEAT_REQUEST;
            case -1 -> DeductResultEnum.BALANCE_NOT_ENOUGH;
            default -> DeductResultEnum.SYSTEM_ERROR;
        };
    }

    // 统一返回码枚举
    public enum DeductResultEnum {
        SUCCESS(0, "扣减成功"),
        REPEAT_REQUEST(1, "重复请求，幂等拦截"),
        BALANCE_NOT_ENOUGH(-1, "余额不足"),
        SYSTEM_ERROR(-99, "系统异常");

        private final int code;
        private final String desc;

        DeductResultEnum(int code, String desc) {
            this.code = code;
            this.desc = desc;
        }

        public int getCode() {
            return code;
        }

        public String getDesc() {
            return desc;
        }
    }
}

进阶：热点分片扣减核心逻辑
技术亮点：解决单热点 Key 性能天花板，通过分片打散实现线性扩容，单账户 QPS 可从 10w 级提升至百万级
import java.util.concurrent.ThreadLocalRandom;

// 分片数：根据预估峰值QPS设置，10分片对应10倍吞吐量提升
private static final int SHARDING_COUNT = 10;

/**
 * 分片版余额扣减：随机选择分片执行扣减，均匀打散热点请求
 */
public DeductResultEnum shardingDeduct(Long accountId, Long deductAmount, String requestNo) {
    // 随机生成分片索引，将请求均匀打散到多个Key上
    int shardIndex = ThreadLocalRandom.current().nextInt(SHARDING_COUNT);
    // 分片余额key格式：account:balance:1001:0 ~ account:balance:1001:9
    String shardBalanceKey = BALANCE_KEY_PREFIX + accountId + ":" + shardIndex;
    String idempotentKey = IDEMPOTENT_KEY_PREFIX + requestNo;

    // 执行分片扣减脚本（单分片余额不足时可扩展跨分片兜底逻辑）
    Long result = stringRedisTemplate.execute(
            balanceDeductScript,
            Arrays.asList(shardBalanceKey, idempotentKey),
            String.valueOf(deductAmount),
            String.valueOf(IDEMPOTENT_EXPIRE_SEC)
    );
    return mapResult(result);
}

// 结果映射复用通用逻辑
private DeductResultEnum mapResult(Long result) {
    return switch (result.intValue()) {
        case 0 -> DeductResultEnum.SUCCESS;
        case 1 -> DeductResultEnum.REPEAT_REQUEST;
        case -1 -> DeductResultEnum.BALANCE_NOT_ENOUGH;
        default -> DeductResultEnum.SYSTEM_ERROR;
    };
}

🎯 核心技术难点与工业级解决方案



技术难点
问题本质
工业级解决方案




单热点 Key 性能天花板
Redis 单线程模型下，单个 Key 的读写 QPS 上限约 10w，超头部热点账户会打满单实例瓶颈
余额分片打散：将单个账户余额拆分为 N 个分片 Key，扣减时随机选择分片执行，总余额为所有分片之和，实现吞吐量线性扩容；配合定时分片间余额调度，避免单分片余额不足导致的扣减失败


Redis 与数据库数据一致性
异步落库架构下，MQ 丢失、服务宕机、Redis 故障都会导致两端余额偏差，直接引发资损风险
三级一致性保障：1. 正常链路：事务消息 MQ 保证落库消息不丢失2. 实时兜底：大额交易同步校验 DB 余额做双重校验3. 日终对账：全量跑批核对 Redis 与 DB，差异自动生成补正流水


重复请求导致重复扣减（幂等性）
接口重试、MQ 重投、网络超时重发会导致同一笔交易多次执行扣减，是资损高频场景
Lua 脚本内置原子幂等：以业务流水号为唯一标识，扣减操作与幂等标记写入打包在同一脚本内，重复请求直接拦截返回成功，彻底避免「先查再扣」的竞态漏洞


Redis 宕机数据丢失风险
Redis 为内存存储，未持久化的数据会随实例宕机丢失，直接造成余额错误
高可用兜底：1. 开启 AOF+RDB 混合持久化，数据丢失窗口控制在 1 秒内2. 主从 + 哨兵集群部署，故障秒级自动切换3. 故障恢复后自动从数据库全量预热余额，兜底数据正确性


余额不足的流量击穿
账户余额为 0 时，大量无效扣减请求持续打到 Redis，占满带宽影响正常业务
应用层本地缓存降级：余额不足的账户在本地缓存短时间标记，后续请求直接在应用层返回，无需穿透到 Redis，减少无效请求占比


Redis 集群整体故障的可用性
Redis 集群全挂时，记账业务不能完全瘫痪，需保障核心交易能力可用
多级降级开关：Redis 不可用时自动降级为数据库乐观锁方案（version版本号控制），牺牲部分性能保障核心交易可用，故障恢复后自动切回 Redis 方案



